from flask import Flask                                                                                                                                                                                                                                             
from calculator import add, subtract                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                    
# 创建一个 Flask 应用对象                                                                                                                                                                                                                                           
app = Flask(__name__)                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                    
# 定义一个网址路由：当访问 /add/数字1/数字2 时，执行下面的函数                                                                                                                                                                                                      
@app.route("/add/<int:a>/<int:b>")                                                                                                                                                                                                                                  
def add_route(a, b):                                                                                                                                                                                                                                                
    result = add(a, b)                                                                                                                                                                                                                                              
    return f"{a} + {b} = {result}\n"                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                    
@app.route("/subtract/<int:a>/<int:b>")                                                                                                                                                                                                                             
def subtract_route(a, b):                                                                                                                                                                                                                                           
    result = subtract(a, b)                                                                                                                                                                                                                                         
    return f"{a} - {b} = {result}\n"                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                    
# 首页，给个提示                                                                                                                                                                                                                                                    
@app.route("/")                                                                                                                                                                                                                                                     
def home():                                                                                                                                                                                                                                                         
    return "计算器服务运行中！试试 /add/2/3 或 /subtract/5/2\n"                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                    
if __name__ == "__main__":                                                                                                                                                                                                                                          
    # 启动服务，监听 0.0.0.0:5000                                                                                                                                                                                                                                   
    # 0.0.0.0 表示接受来自任何地址的访问（Docker 里必须这样写，不能用 127.0.0.1）                                                                                                                                                                                   
    app.run(host="0.0.0.0", port=5000, threaded=True)  